/* From Uiverse.io by JohnnyCSilva - Tags: card, crypto, ethereum */
.__UIV_SCOPE__ .card {
  width: 195px;
  height: 285px;
  background: #313131;
  border-radius: 20px;
  ;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: white;
  transition: 0.2s ease-in-out;
}

.__UIV_SCOPE__ .img {
  height: 30%;
  position: absolute;
  transition: 0.2s ease-in-out;
  z-index: 1;
}

.__UIV_SCOPE__ .textBox {
  opacity: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 15px;
  transition: 0.2s ease-in-out;
  z-index: 2;
}

.__UIV_SCOPE__ .textBox > .text {
  font-weight: bold;
}

.__UIV_SCOPE__ .textBox > .head {
  font-size: 20px;
}

.__UIV_SCOPE__ .textBox > .price {
  font-size: 17px;
}

.__UIV_SCOPE__ .textBox > span {
  font-size: 12px;
  color: lightgrey;
}

.__UIV_SCOPE__ .card:hover > .textBox {
  opacity: 1;
}

.__UIV_SCOPE__ .card:hover > .img {
  height: 65%;
  filter: blur(7px);
  animation: anim 3s infinite;
}

@keyframes anim {
  0% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-20px);
  }

  100% {
    transform: translateY(0);
  }
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.04) rotate(-1deg);
}
